#!/bin/sh
# Public Debian 12 AArch64 reference cross qualification of opencv_geometry.
#
# Runs inside the environment of tests/cross/install_reference_tools.sh.
# It prepares public reference inputs:
#   1. a sysroot staged from Debian 12 arm64 packages;
#   2. a GPR configuration generated by GPRconfig 26 for Debian's
#      gnat-12-aarch64-linux-gnu and g++-12-aarch64-linux-gnu;
# and then runs tests/cross/qualify_target.sh with them: Core and Geometry
# cross-built and installed, independent consumers cross-linked before and
# after relocation, and the consumers and the cross-built AUnit suite run
# under qemu-user-static.
#
# This is public reference evidence. It is not AdaCore GNAT 12 or Yocto
# Scarthgap qualification, and emulated execution is not target execution.
#
# usage: qualify_debian_aarch64_reference.sh EVIDENCE
# Inputs:
#   REFERENCE_CORE_ROOT    clean opencv_core Git checkout
#   REFERENCE_CORE_COMMIT  40-hex Core commit expected there
#   REFERENCE_AUNIT_ROOT   unpacked AUnit 26.0.0 sources
set -eu

fail() {
    echo "error: $*" >&2
    exit 1
}

here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
root=$(CDPATH='' cd -- "$here/../.." && pwd)
test "$#" -eq 1 || fail "usage: qualify_debian_aarch64_reference.sh EVIDENCE"
evidence=$1
core_root=${REFERENCE_CORE_ROOT:?set REFERENCE_CORE_ROOT}
core_commit=${REFERENCE_CORE_COMMIT:?set REFERENCE_CORE_COMMIT}
aunit=${REFERENCE_AUNIT_ROOT:?set REFERENCE_AUNIT_ROOT}
case "$evidence" in /?*) ;; *) fail "absolute evidence path required" ;; esac
test ! -e "$evidence" || fail "evidence directory already exists"
for host in gcc g++ gnat gprbuild; do
    if command -v "$host" >/dev/null 2>&1; then
        fail "host tool on PATH: $host"
    fi
done

target=aarch64-linux-gnu
tools=/opt/gprbuild-26/bin
logs=$evidence/logs
mkdir -p "$logs" "$evidence/tools"
: > "$evidence/dispositions.txt"

# 1. Target sysroot from real Debian 12 arm64 packages.
sysroot=$evidence/sysroot
sh "$here/prepare_debian12_sysroot.sh" "$sysroot" "$logs" \
    > "$logs/sysroot.log" 2>&1 || fail "sysroot staging failed"

# 2. GPR configuration. GPRconfig's non-Pro C++ discovery recognizes an
#    unprefixed g++, so the explicit cross g++ is presented through a
#    dedicated tools directory.
ln -s /usr/bin/aarch64-linux-gnu-g++-12 "$evidence/tools/g++"
config=$evidence/target.cgpr
"$tools/gprconfig" --batch --target="$target" \
    --config="Ada,,/usr/lib/gcc-cross/aarch64-linux-gnu/12" \
    --config="C++,,,$evidence/tools" -o "$config" \
    > "$logs/gprconfig.log" 2>&1 || fail "GPR configuration failed"
cp "$config" "$logs/target.cgpr"
{
    echo "geometry: $(git -c "safe.directory=$root" -C "$root" rev-parse HEAD)"
    echo "core: $core_commit"
    cat /etc/os-release
    dpkg-query -W gcc-12-aarch64-linux-gnu g++-12-aarch64-linux-gnu \
        gnat-12-aarch64-linux-gnu libgnat-12-arm64-cross \
        binutils-aarch64-linux-gnu qemu-user-static
    /usr/bin/aarch64-linux-gnu-gcc --version
    /usr/bin/aarch64-linux-gnu-g++-12 --version
    "$tools/gprbuild" --version
    sha256sum "$config"
} > "$logs/identities.log" 2>&1

export OPENCV_CROSS_TARGET="$target"
export ENV_PREFIX="$sysroot"
export OPENCV_CROSS_ADA=/usr/bin/aarch64-linux-gnu-gcc
export OPENCV_CROSS_CXX="$evidence/tools/g++"
export OPENCV_CROSS_RUNTIME=/usr/lib/gcc-cross/aarch64-linux-gnu/12
export OPENCV_CROSS_GPR_CONFIG="$config"
export OPENCV_CROSS_GPRBUILD="$tools/gprbuild"
export OPENCV_CROSS_GPRINSTALL="$tools/gprinstall"
export OPENCV_CROSS_PKG_CONFIG=/usr/bin/pkg-config
export OPENCV_CROSS_READELF=/usr/bin/readelf
export PKG_CONFIG_LIBDIR="$sysroot/usr/lib/aarch64-linux-gnu/pkgconfig"
export PKG_CONFIG_SYSROOT_DIR="$sysroot"
export OPENCV_CROSS_PROFILE=release
unset PKG_CONFIG_PATH GPR_PROJECT_PATH ADA_PROJECT_PATH CPATH
unset C_INCLUDE_PATH CPLUS_INCLUDE_PATH LIBRARY_PATH GCC_EXEC_PREFIX
unset COMPILER_PATH LD_LIBRARY_PATH ADA_INCLUDE_PATH ADA_OBJECTS_PATH
unset OPENCV_CROSS_CORE_PREFIX

QUALIFY_CORE_ROOT="$core_root" QUALIFY_CORE_COMMIT="$core_commit" \
QUALIFY_AUNIT_ROOT="$aunit" QUALIFY_EMULATOR=/usr/bin/qemu-aarch64-static \
    sh "$here/qualify_target.sh" "$evidence"

# Negative control on real data: AdaCore GNAT 12 / Yocto Scarthgap claims
# about these Debian inputs must be rejected by the binary evidence.
claims=$evidence/false-claims.json
cat > "$claims" <<EOF
{"yocto": {"release": "scarthgap", "distro": "poky", "machine": "claimed",
           "image": "claimed", "build_identity": "claimed",
           "export_method": "claimed", "sysroot": "$sysroot"},
 "toolchain": {"vendor": "AdaCore", "product": "GNAT Pro", "gnat_major": 12}}
EOF
if OPENCV_CROSS_YOCTO_PROVENANCE="$claims" \
    sh "$here/qualify_adacore_yocto.sh" "$evidence/false-claims" \
    > "$logs/false-claims.log" 2>&1; then
    fail "AdaCore/Yocto claims about Debian inputs were accepted"
fi
rejection=$evidence/false-claims/dispositions.txt
grep -q '^ADACORE_YOCTO_QUALIFICATION_BLOCKED (claims not verified' \
    "$rejection" || fail "the adapter did not block on the claims"
grep -q 'Yocto release claim cannot be verified\|contradicts yocto.release' \
    "$rejection" || fail "the Yocto claim was not rejected"
grep -q 'identify GNAT Pro' "$rejection" \
    || fail "the AdaCore claim was not rejected"
if grep -q '_QUALIFIED' "$rejection"; then
    fail "the rejected adapter run printed a qualified state"
fi
cp "$rejection" "$logs/false-claims-dispositions.txt"
echo "ADACORE_YOCTO_CLAIMS_ON_DEBIAN_INPUTS REJECTED (negative control)" \
    >> "$evidence/dispositions.txt"
echo "REFERENCE_INPUTS Debian 12 gnat-12-aarch64-linux-gnu and arm64" \
    "packages: emulated results are reference only; AdaCore GNAT 12 and" \
    "Yocto Scarthgap NOT ESTABLISHED" >> "$evidence/dispositions.txt"
cat "$evidence/dispositions.txt"
